"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2936],{26287:e=>{e.exports=JSON.parse('{"functions":[{"name":"isOversized","desc":"Whether an item of this size counts as oversized, by comparing its magnitude\\nagainst `OVERSIZED_ITEM_THRESHOLD`.\\n\\nOversized items get the two-handed hold animation and are excluded from the\\nhotbar.","params":[{"name":"size","desc":"Size of the item\'s primary part","lua_type":"Vector3"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":72,"path":"src/Shared/Class/Character.luau"}},{"name":"removeHeldItem","desc":"Destroys the character\'s held item, if it has one.\\n\\nDestroying the model also tears down its hold animation track. A `nil` character\\nis a no-op, so this is safe to call during respawn teardown.","params":[{"name":"character","desc":"Character to clear","lua_type":"Model?"}],"returns":[],"function_type":"static","source":{"line":87,"path":"src/Shared/Class/Character.luau"}},{"name":"newHeldItem","desc":"Attaches a held item model to the character, replacing whatever it was holding.\\n\\nThe model is **consumed**, not copied: it is renamed, reparented under the\\ncharacter, and every descendant part is made massless, non-colliding and\\nnon-queryable so it cannot disturb the character\'s physics. Pass a clone if you\\nneed to keep the original.\\n\\nReturns early with a warning if `model` has no `PrimaryPart`, and silently if the\\ncharacter has no `RightHand`.\\n\\nThe hold animation is chosen in order of precedence: the `animationId` argument, a\\n`HoldAnimation` string attribute on the model, then the default or oversized\\nanimation depending on [CharacterGrip.isOversized]. The track loops at `Action`\\npriority and is destroyed with the model.\\n\\n```lua\\nCharacter.newHeldItem(character, toolModel:Clone())\\n```","params":[{"name":"character","desc":"Character to attach to","lua_type":"Model"},{"name":"model","desc":"Item model; must have a PrimaryPart","lua_type":"Model"},{"name":"animationId","desc":"Overrides the default hold animation","lua_type":"string?"}],"returns":[],"function_type":"static","source":{"line":126,"path":"src/Shared/Class/Character.luau"}},{"name":"applyDefaultDescription","desc":"Flattens a [HumanoidDescription] to the game\'s uniform body: default scales and\\nevery body part and face cleared to 0.\\n\\nThis deliberately discards the player\'s avatar so every character reads at the same\\nsize, which the held-item grip offsets and animations assume. Mutates the\\ndescription in place \u2014 apply it to a Humanoid afterwards.","params":[{"name":"description","desc":"Description to normalize","lua_type":"HumanoidDescription"}],"returns":[],"function_type":"static","source":{"line":218,"path":"src/Shared/Class/Character.luau"}}],"properties":[],"types":[],"name":"CharacterGrip","desc":"Attaches held-item models to a character\'s right hand and normalizes avatar\\nproportions.\\n\\nA held item is welded to a `RightGripAttachment` on the character\'s `RightHand`,\\nrenamed to `__HeldItem`, and parented to the character \u2014 so there is only ever one,\\nand finding or clearing it is a name lookup. Grip attachments are created on demand\\nif the hand or the model does not already have one.\\n\\nConstants:\\n\\n- `HELD_ITEM_NAME` \u2014 `\\"__HeldItem\\"`, the name every held model is given.\\n- `OVERSIZED_ITEM_THRESHOLD` \u2014 items whose primary part magnitude exceeds this are\\n  treated as oversized and get the two-handed hold animation.\\n- `HELD_ITEM_ANIMATION` / `HELD_ITEM_OVERSIZED_ANIMATION` \u2014 the default hold\\n  animation ids.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":23,"path":"src/Shared/Class/Character.luau"}}')}}]);